const fs = require('fs');
const path = require('path');

const inputPath = path.join(__dirname, 'config.json');
const outputPath = path.join(__dirname, 'config.out.json');

const raw = fs.readFileSync(inputPath, 'utf8');
const cfg = raw.trim() ? JSON.parse(raw) : {};

if (cfg.port === undefined) cfg.port = 3000;
if (cfg.host === undefined) cfg.host = '127.0.0.1';

fs.writeFileSync(outputPath, JSON.stringify(cfg, null, 2) + '\n');
console.log('OK');

